head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > dynamic]<br/>GridView 에 내부 정의가 없을때 경고 메시지 출력 여부를 설정합니다.",
    "validation" : [
        "true 설정 시, '<w2:header>', '<w2:body>' 등의 노드 정의가 없어도 경고 메시지를 출력하지 않습니다.",
        "false 설정 시, '<w2:header>', '<w2:body>' 등의 노드 정의가 없을때 경고 메시지를 출력합니다.",
        "미설정 시, '<w2:header>', '<w2:body>' 등의 노드 정의가 없을때 경고 메시지를 출력합니다."
    ]
}



// 경고 관찰 상태 저장소 (lastWarnMsgs : 이번 생성분에서 캡처한 경고 메시지 원문 배열)
scwin.gVar = { "dynApplied" : "", "lastWarnMsgs" : [] };



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdl_boolean 등)
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 미적용 -> 기본값 명시 설정 (gdl_boolean 코드값 미설정="1"/true="2"/false="3")
    //  dynamic 기본값 false -> 코드 "3" 으로 시작 (노드 없으면 경고 출력되는 케이스).
    con_dynamic.setValue("3");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  dynamic 은 렌더 시 결정되는 속성이므로 con 변경 후 "Target 재생성"(btn_createTarget -> comp_init) 으로만 반영한다.
//  대상 그리드는 header/gBody 정의가 없는 "빈(node-less) GridView(기본틀)" 로 생성해야 uncompleted 조건이 성립하여
//  dynamic 값에 따른 경고 출력/미출력 을 검증할 수 있다.
//
//  [크래시 처리] node-less GridView 를 동적 생성하면, 엔진이 appendTo 단계에서 toHTML() 이 undefined(uncompleted)라
//   TypeError(...wq_trim...)를 던지는데 이는 xfControl.appendTo 내부 try/catch 가 삼켜 console.error 로 로깅한다
//   (외부 try/catch 로는 못 막음). 따라서 생성 구간 동안 console.error 를 임시 후킹하여 해당 양성(benign) 에러만
//   걸러낸다. dynamic 값에 따른 $l 경고(gridView.js:516)는 그 이전에 이미 WebSquare 로그버퍼(logMsgArray)에 적재되므로
//   그대로 캡처 가능하다.
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 테스트 참고 라벨 (가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] con_dynamic (true/false/미설정) 선택값으로 header/gBody 정의가 없는 빈 GridView(기본틀) target1 을 동적 생성한다. 내부 노드가 없으면 uncompleted 상태가 되어 dynamic 값에 따라 경고 메시지 출력 여부가 갈린다. dynamic 미설정은 엔진 기본값 false 로 동작. 빈 그리드는 화면에 표시되지 않으며 경고는 브라우저 콘솔이 아닌 WebSquare 로그버퍼(logMsgArray)에 적재된다(본 빌드 printConsole=false).\n[절차] con_dynamic 선택 -> Target 재생성. 재생성 직후 하단 결과창에 경고 출력 여부가 자동 표시된다. [경고 로그 확인] 버튼으로 현재 값을 다시 확인할 수 있다.\n[확인] dynamic true = 경고 미출력 / dynamic false·미설정 = 경고 출력 (gridView error : cannot find <w2:header> or <w2:gBody>)."', '', 'label1');

    // con 선택값 (gdl_boolean 바인딩 -> getText() 로 라벨(''/'true'/'false') 분기)
    var dynamic = con_dynamic.getText();
    scwin.gVar.dynApplied = (dynamic === '' ? "미설정(기본 false)" : dynamic);

    // 빈(node-less) GridView 마크업 : header/gBody/dataList 없이 gridView 태그만.
    //  dynamic 미설정이면 속성 자체를 넣지 않아 엔진 기본값(false)을 적용.
    var ns = $c.gcm.getNameSpace();
    var strTarget = '<w2:gridView ' + ns + ' id="" style="width:640px;height:40px;"';
    if (dynamic === 'true' || dynamic === 'false') {
        strTarget += ' dynamic="' + dynamic + '"';
    }
    strTarget += '></w2:gridView>';

    var grp_comp = $c.gcm.getTestGroup();

    // 이번 생성분만 판정하기 위한 logMsgArray 기준선(단일 target 재생성 시 id 가 동일해 과거 경고가 누적되므로 slice 필요)
    var baseline = (window.WebSquare && window.WebSquare.logMsgArray) ? window.WebSquare.logMsgArray.length : 0;

    // 양성 appendTo 에러(node-less) 만 걸러내는 console.error 임시 후킹
    var origErr = console.error;
    console.error = function () {
        try {
            var j = Array.prototype.map.call(arguments, function (a) { return (a && a.message) ? a.message : String(a); }).join(' ');
            if (j.indexOf('wq_trim') !== -1 || j.indexOf('cannot find <w2:header>') !== -1) {
                return; // node-less GridView 생성 시의 양성 에러 -> 무시
            }
        } catch (ex) {}
        return origErr.apply(console, arguments);
    };

    try {
        scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
    } catch (ex) {
        // 방어적 흡수 (엔진이 내부에서 이미 처리하지만 혹시 propagate 되어도 콘솔 오류로 새지 않게)
    } finally {
        console.error = origErr;
    }

    // 이번 생성분(baseline 이후)에서 캡처된 경고 메시지 원문 수집
    scwin.gVar.lastWarnMsgs = scwin.warnMessagesSince(baseline);

    // 재생성 직후 자동 보고 (wf_body_bottom 준비 시점 확보 위해 setTimeout 으로 미룸)
    setTimeout(function () { scwin.reportWarn(); }, 0);
}



// logMsgArray 의 baseline 이후 항목에서 "cannot find <w2:header> or <w2:gBody>" 경고 메시지 원문 수집
//  logMsgArray 항목은 앞에 타임스탬프 prefix 가 붙으므로 "gridView error" 부터의 실제 메시지 원문만 추출한다.
scwin.warnMessagesSince = function (baseline) {
    var wg = window.WebSquare;
    var arr = (wg && wg.logMsgArray) ? wg.logMsgArray : [];
    var out = [];
    for (var i = baseline; i < arr.length; i++) {
        var s = arr[i];
        if (typeof s === 'string' && s.indexOf("cannot find <w2:header> or <w2:gBody>") !== -1) {
            var idx = s.indexOf("gridView error");
            out.push(idx !== -1 ? s.substring(idx).replace(/^\s+/, '') : s);
        }
    }
    return out;
}



// 현재 dynamic 값에 따른 경고 메시지 원문을 결과창에 그대로 출력 (없으면 '경고 메시지 없음')
scwin.reportWarn = function () {
    var b;
    try { b = wf_body_bottom.getObj("scwin"); } catch (ex) { return; }
    if (!b) return;
    var msgs = scwin.gVar.lastWarnMsgs || [];
    if (msgs.length > 0) {
        b.setReturnValue("[dynamic=" + scwin.gVar.dynApplied + "] 캡처된 경고 메시지 (원문) :");
        for (var i = 0; i < msgs.length; i++) {
            b.setReturnValue(msgs[i]);
        }
    } else {
        b.setReturnValue("[dynamic=" + scwin.gVar.dynApplied + "] 경고 메시지 없음");
    }
}



// (검증1~3) 현재 con 값으로 생성된 target1 의 경고 출력 여부 재확인
scwin.btn_checkWarn_onclick = function () {
    scwin.reportWarn();
}
